//! How a command-line client splits a script into statements.
//!
//! Some SQL is never sent to the server as written. A command-line client
//! reads the script line by line, splits it into statements itself and handles
//! some of the text before anything reaches the server. [`ClientCommandRules`]
//! describes a client. The lexer's `client_script` module lexes with it, and
//! `sqlfluff.core.parser.client_commands` is the Python equivalent: the two
//! must emit identical tokens.
//!
//! Dialects get their rules from code generated by `utils/build_lexers.py`, so
//! everything here is `'static` and can be built in a `static`.

/// What a client command reads after its name.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ArgumentKind {
    /// A new statement delimiter, e.g. `DELIMITER $$`.
    Delimiter,
    /// A script to run, e.g. `SOURCE file.sql`.
    FileName,
}

/// What a short command does to the statement it appears in.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BufferAction {
    /// The statement carries on, e.g. `\d`.
    Keep,
    /// The statement is sent to the server, as at the delimiter, e.g. `\g`.
    End,
    /// The statement is thrown away, e.g. `\.`.
    Discard,
}

/// A long-form command, e.g. `DELIMITER $$`. It must be the entire statement.
///
/// It runs alone on its line at the start of a statement, or as a statement
/// collected up to the delimiter. So it never acts on SQL around it.
#[derive(Debug, Clone, Copy)]
pub struct LongClientCommand {
    /// In lower case, matched in any case.
    pub name: &'static str,
    pub argument: ArgumentKind,
}

/// A command that runs wherever it appears outside strings and comments.
///
/// E.g. `\d $$`, which may come in the middle of a statement.
#[derive(Debug, Clone, Copy)]
pub struct ShortClientCommand {
    /// Matched in its own case, e.g. `\d`.
    pub text: &'static str,
    pub buffer_action: BufferAction,
    pub argument: Option<ArgumentKind>,
}

/// How a command-line client splits a script into statements.
#[derive(Debug, Clone, Copy)]
pub struct ClientCommandRules {
    pub long_commands: &'static [LongClientCommand],
    pub short_commands: &'static [ShortClientCommand],
    /// Lexer matchers whose text the client doesn't scan: strings, quoted
    /// identifiers and comments. The delimiter isn't found inside these.
    pub opaque_token_names: &'static [&'static str],
    /// Whether a `/* ... */` comment may come before a long-form command that
    /// takes its line. A command the client collects as a statement may follow
    /// a comment either way.
    pub line_command_after_block_comment: bool,
    /// Whether `--` starts a comment at the start of a statement even with no
    /// whitespace after it. Elsewhere `--` needs whitespace or the end of the
    /// line after it, which is the dialect's comment matcher's job.
    pub dash_dash_comment_at_statement_start: bool,
    /// A line holding this text is never a long-form command line: the client
    /// collects it as a statement instead. For no apparent reason the mysql
    /// client only checks for a lower-case `\g` here, though `\G` ends a
    /// statement just the same: `SOURCE x.sql \G` reads a file named `x.sql \G`.
    pub collected_line_marker: Option<&'static str>,
    pub default_delimiter: &'static str,
    /// If set, longer delimiters are cut to this many bytes, as the client
    /// does. `None` for no limit.
    pub max_delimiter_bytes: Option<usize>,
}

impl ClientCommandRules {
    /// The long command called `name`, in any case.
    #[must_use]
    pub fn command_named(&self, name: &str) -> Option<&'static LongClientCommand> {
        self.long_commands
            .iter()
            .find(|command| command.name.eq_ignore_ascii_case(name))
    }

    /// The short command that starts `text`.
    #[must_use]
    pub fn command_starting(&self, text: &str) -> Option<&'static ShortClientCommand> {
        self.short_commands
            .iter()
            .find(|command| text.starts_with(command.text))
    }

    /// Whether the client scans the text of tokens from the matcher `name`.
    #[must_use]
    pub fn is_opaque(&self, name: &str) -> bool {
        self.opaque_token_names.contains(&name)
    }
}
